INSERT INTO _cex_wave_e_profiles_0095 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'bitmart', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:bitmart","type":"cex","slug":"bitmart","name":"BitMart","aliases":["BitMart Exchange"]},"classification":{"subtype":"custodial multi-product exchange in announced wind-down","tags":["custodial","spot","derivatives","wind-down","exchange-token"],"chains":[],"jurisdictions":["global"]},"status":{"operating_state":"winding_down","as_of":"2026-08-03","claim_ids":["claim:bitmart:status"]},"outcome":{"label":"orderly_wind_down_announced","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:bitmart:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"BitMart is a custodial exchange that has offered spot, derivatives and other crypto services through accounts controlled by the venue. It also issued BMX, a separate exchange utility token. On July 26, 2026 BitMart announced a phased shutdown, so the useful description today is not simply “active” or “dead”: it is an exchange still processing an orderly wind-down under a published timetable.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:what_it_is:1","claim:bitmart:section:what_it_is:2","claim:bitmart:section:what_it_is:3"]},"what_happened":{"body":"BitMart stopped new registrations, deposits and new orders beginning July 26, 2026. It scheduled all trading to end August 26 and the full platform to close January 31, 2027, while urging customers to withdraw before the trading cutoff. The announcement followed May restrictions on 239 linked accounts and a much older 2021 hot-wallet breach, but the public record does not establish either episode as the cause of the shutdown.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:what_happened:1","claim:bitmart:section:what_happened:2","claim:bitmart:section:what_happened:3"]},"why_this_outcome":{"body":"The only direct explanation from BitMart is a review of operating conditions, the market environment and future strategic direction. That supports a strategic-exit reading, but it is too vague to distinguish weak economics, compliance cost, owner preference or another constraint. BMX falling 58% on the news shows that token holders treated the venue closure as material; it does not reveal why management made the decision.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:why_this_outcome:1","claim:bitmart:section:why_this_outcome:2","claim:bitmart:section:why_this_outcome:3"]},"strategic_choices":{"body":"BitMart chose a broad global product menu and tied platform benefits to BMX, including a fee-funded repurchase-and-burn design. It also chose a long phased exit rather than an immediate platform stop, leaving months for trading and withdrawals before final closure. That can reduce operational shock if execution works. It also creates a long period in which customers must judge withdrawal performance without a published proof-of-reserves report.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:strategic_choices:1","claim:bitmart:section:strategic_choices:2","claim:bitmart:section:strategic_choices:3"]},"operating_model":{"body":"Customers deposited assets with BitMart, traded on its internal order books and relied on the venue to process withdrawals. Revenue could come from trading and service fees, while the BMX design directed a stated portion of fees toward repurchases and burns. The reviewed record does not publish a current exchange-level income statement, customer-liability schedule or audited reserve reconciliation, so trading activity cannot be translated into solvency or profitability.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:operating_model:1","claim:bitmart:section:operating_model:2","claim:bitmart:section:operating_model:3"]},"token_and_value_capture":{"body":"BMX was issued with an initial supply of one billion and was designed for exchange benefits plus repurchase-and-burn demand funded from fees. That connected token utility to continued platform use, which became a weakness once closure was announced. The reported 58% price fall is consistent with that dependency, but a market price reaction is not proof of the token’s future legal status, remaining treasury assets or final redemption value.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:token_and_value_capture:1","claim:bitmart:section:token_and_value_capture:2","claim:bitmart:section:token_and_value_capture:3"]},"counterfactual":{"body":"A credible reserve report, clearer entity-level financial disclosure and earlier explanation of the strategic problem could have given customers and token holders more information before the exit. A narrower product or jurisdiction footprint might also have reduced operating burden, but there is no published evidence that it would have preserved the business. The real counterfactual is whether transparent reserves and profitable core markets existed; public documents do not answer it.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:counterfactual:1","claim:bitmart:section:counterfactual:2","claim:bitmart:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The immediate risk is execution: customers need withdrawals processed before services end, but the reviewed record contains no current completion-rate or liability-coverage data. There is also governance uncertainty because the closure notice does not identify a specific economic trigger. The 2021 stolen-key breach is relevant custody history, yet BitMart said it would compensate users; it should not be presented as an unpaid 2026 shortfall without new evidence.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:risks_and_unknowns:1","claim:bitmart:section:risks_and_unknowns:2","claim:bitmart:section:risks_and_unknowns:3"]},"lifecycle":{"body":"BitMart launched in 2017, built a global custodial exchange and exchange-token model, suffered a major hot-wallet compromise in 2021, restricted suspicious linked accounts in May 2026 and announced closure two months later. The platform has not yet reached its final scheduled end date of January 31, 2027. Its lifecycle label is “winding down,” with the final outcome dependent on withdrawals, residual claims and completion of the timetable.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:lifecycle:1","claim:bitmart:section:lifecycle:2","claim:bitmart:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch whether trading stops on August 26, whether withdrawals remain available and timely, whether BitMart publishes reserve or liability data, and what happens to BMX benefits and treasury controls. A clean outcome means customers exit on schedule with few unresolved claims. A worse outcome means withdrawal friction, date changes or material liabilities emerge. Until those facts are known, this is an unresolved wind-down rather than a completed failure.","as_of":"2026-08-03","claim_ids":["claim:bitmart:section:outlook_and_watch:1","claim:bitmart:section:outlook_and_watch:2","claim:bitmart:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:bitmart:breach-estimate:2021-12-05","dimension":"customer_shortfall","label":"Independent 2021 breach loss estimate","value":196000000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2021-12-05","definition":"incident estimate"},"as_of":"2021-12-05","method":"Independent estimate paired with operator incident scope.","scope":{"product":"two BitMart hot wallets","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bitmart:metric:breach-estimate"],"quality_flags":["third_party_estimate","historical_incident","operator_said_users_would_be_compensated","not_current_shortfall"]}],"events":[{"id":"event:bitmart:breach","type":"security","date":"2021-12-05","description":"BitMart reported a stolen private key affecting two hot wallets and said it would compensate affected users.","claim_ids":["claim:bitmart:event:breach"]},{"id":"event:bitmart:account-controls","type":"risk_control","date":"2026-05-23","description":"BitMart described restrictions on 239 linked accounts and said proof of reserves was not yet published.","claim_ids":["claim:bitmart:event:account-controls"]},{"id":"event:bitmart:wind-down","type":"closure","date":"2026-07-26","description":"BitMart announced its phased cessation schedule.","claim_ids":["claim:bitmart:event:wind-down"]}],"sources":[{"id":"source:bitmart:closure","title":"Important notice regarding the orderly cessation of BitMart operations","url":"https://bitmart.zendesk.com/hc/en-us/articles/53544595916059-Important-Notice-Regarding-the-Orderly-Cessation-of-BitMart-Operations","publisher":"BitMart","published_at":"2026-07-26","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Official wind-down announcement, product cutoffs, withdrawal recommendation and final platform-closure date.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bitmart:controls","title":"Statement on unusual trading activity and account restrictions","url":"https://www.bitmart.com/en-US/support/articles/7922665245339/39162120325403/50773623099035","publisher":"BitMart","published_at":"2026-05-23","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Operator account-restriction explanation and statement that proof of reserves had not yet been published.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bitmart:breach","title":"BitMart security breach update","url":"https://www.bitmart.com/en-US/support/articles/7922665245339/7923672421147/4411998987419","publisher":"BitMart","published_at":"2021-12-05","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Operator description of two affected hot wallets, a stolen private key and compensation commitment.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bitmart:bmx","title":"BMX token","url":"https://www.bitmart.com/en-US/bmx","publisher":"BitMart","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current BMX token, timelock and multisignature-control page.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bitmart:bmx-supply","title":"What is BMX?","url":"https://www.bitmart.com/en-US/support/articles/7949433565211/360000415634/360003185273","publisher":"BitMart","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Initial one-billion BMX supply and fee-funded repurchase-and-burn description.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bitmart:coindesk-close","title":"Crypto exchange BitMart to shut down after nine years","url":"https://www.coindesk.com/markets/2026/07/26/crypto-exchange-bitmart-to-shut-down-after-nine-years-bmx-token-crashes-58","publisher":"CoinDesk","published_at":"2026-07-26","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent closure coverage and event-window BMX price reaction.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bitmart:breach-independent","title":"BitMart hacked, losses estimated at $196 million","url":"https://beincrypto.com/bitmart-hacked-losses-estimated-at-196m/","publisher":"BeInCrypto","published_at":"2021-12-05","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent report of PeckShield''s approximate 2021 loss estimate.","direct_http_status":403,"access_method":"browser_rendered_page"}],"claims":[{"id":"claim:bitmart:status","field_path":"status.operating_state","assertion":"BitMart was in an announced wind-down at the review date, with all trading scheduled to stop on August 26, 2026 and the platform scheduled to close on January 31, 2027.","value":"winding_down","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure","source:bitmart:coindesk-close"],"evidence_locator":"Official cessation schedule and independent contemporaneous coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:outcome","field_path":"outcome.label","assertion":"BitMart is classified as winding down, not already closed or proven insolvent.","value":"orderly_wind_down_announced","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:closure","source:bitmart:controls","source:bitmart:coindesk-close"],"evidence_locator":"The operator published a future closure schedule but did not disclose insolvency or a final financial cause.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"BitMart operates a custodial multi-product exchange.","value":"BitMart operates a custodial multi-product exchange.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure","source:bitmart:controls"],"evidence_locator":"Current operator notices and product restrictions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"BMX is a separate exchange token rather than customer equity.","value":"BMX is a separate exchange token rather than customer equity.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:bmx","source:bitmart:bmx-supply"],"evidence_locator":"Current token and supply pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"The venue was winding down rather than fully closed on August 3, 2026.","value":"The venue was winding down rather than fully closed on August 3, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure"],"evidence_locator":"Future trading and closure dates in the official schedule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Registrations, deposits and new orders were scheduled to stop from July 26, 2026.","value":"Registrations, deposits and new orders were scheduled to stop from July 26, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure"],"evidence_locator":"Official phase-one timetable.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Trading was scheduled to end August 26, 2026 and the platform January 31, 2027.","value":"Trading was scheduled to end August 26, 2026 and the platform January 31, 2027.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure"],"evidence_locator":"Official phase-two and final dates.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The May controls and 2021 breach are not established causes of the 2026 closure.","value":"The May controls and 2021 breach are not established causes of the 2026 closure.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure","source:bitmart:controls","source:bitmart:breach"],"evidence_locator":"The closure notice does not make that causal link.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"BitMart cited operating conditions, market environment and future strategic direction.","value":"BitMart cited operating conditions, market environment and future strategic direction.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure"],"evidence_locator":"Operator explanation in the cessation notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The public explanation does not isolate a financial or regulatory cause.","value":"The public explanation does not isolate a financial or regulatory cause.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure"],"evidence_locator":"No causal balance sheet, regulator order or board record is published.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"BMX fell 58% around the closure announcement according to CoinDesk.","value":"BMX fell 58% around the closure announcement according to CoinDesk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:coindesk-close"],"evidence_locator":"Independent event-window reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"BitMart linked BMX economics to exchange fees and token burns.","value":"BitMart linked BMX economics to exchange fees and token burns.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:bmx-supply","source:bitmart:bmx"],"evidence_locator":"Operator token design pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"BitMart chose a phased rather than immediate closure.","value":"BitMart chose a phased rather than immediate closure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:closure"],"evidence_locator":"Published six-month wind-down timetable.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"BitMart said in May 2026 that proof of reserves had not yet been published.","value":"BitMart said in May 2026 that proof of reserves had not yet been published.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:controls"],"evidence_locator":"Operator transparency statement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"BitMart used custodial accounts and internal trading controls.","value":"BitMart used custodial accounts and internal trading controls.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:controls","source:bitmart:closure"],"evidence_locator":"Account restriction and trading-cutoff mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"The BMX design described fee-funded repurchases and burns.","value":"The BMX design described fee-funded repurchases and burns.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:bmx-supply"],"evidence_locator":"Operator token economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"Current audited venue profitability and liabilities are not published in the reviewed sources.","value":"Current audited venue profitability and liabilities are not published in the reviewed sources.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure","source:bitmart:controls"],"evidence_locator":"Disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"BMX had an initial stated supply of one billion tokens.","value":"BMX had an initial stated supply of one billion tokens.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:bmx-supply"],"evidence_locator":"Operator supply description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Exchange-fee repurchases and burns were a stated BMX value-capture mechanism.","value":"Exchange-fee repurchases and burns were a stated BMX value-capture mechanism.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:bmx-supply","source:bitmart:bmx"],"evidence_locator":"Operator economics and control pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Post-closure BMX utility and redemption rights are not established by the reviewed record.","value":"Post-closure BMX utility and redemption rights are not established by the reviewed record.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure","source:bitmart:bmx"],"evidence_locator":"Closure and token pages do not resolve the post-platform state.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"BitMart had not published proof of reserves by May 2026.","value":"BitMart had not published proof of reserves by May 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:controls"],"evidence_locator":"Operator statement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Earlier financial disclosure could have reduced information risk during a wind-down.","value":"Earlier financial disclosure could have reduced information risk during a wind-down.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:controls","source:bitmart:closure"],"evidence_locator":"Analyst counterfactual based on the disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Whether a narrower business would have prevented closure is unknown.","value":"Whether a narrower business would have prevented closure is unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure"],"evidence_locator":"The operator did not publish segment economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Withdrawal execution is the principal customer risk during the scheduled closure.","value":"Withdrawal execution is the principal customer risk during the scheduled closure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:closure"],"evidence_locator":"Operator withdrawal recommendation and cutoff schedule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The 2021 incident involved two hot wallets and a stolen private key.","value":"The 2021 incident involved two hot wallets and a stolen private key.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:breach","source:bitmart:breach-independent"],"evidence_locator":"Operator incident description and independent estimate.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The reviewed record does not establish a current unpaid shortfall from that incident.","value":"The reviewed record does not establish a current unpaid shortfall from that incident.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:breach","source:bitmart:closure"],"evidence_locator":"Operator compensation statement and absence of a current contrary finding.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"BitMart operated for roughly nine years before announcing closure.","value":"BitMart operated for roughly nine years before announcing closure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:coindesk-close"],"evidence_locator":"Independent operating-history summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"A 2021 breach and May 2026 account restrictions preceded the closure announcement.","value":"A 2021 breach and May 2026 account restrictions preceded the closure announcement.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:breach","source:bitmart:controls","source:bitmart:closure"],"evidence_locator":"Dated sequence without causal assertion.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"Final closure was scheduled for January 31, 2027.","value":"Final closure was scheduled for January 31, 2027.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure"],"evidence_locator":"Official final platform date.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"The August trading cutoff and January closure date are observable milestones.","value":"The August trading cutoff and January closure date are observable milestones.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:closure"],"evidence_locator":"Official schedule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Reserve disclosure and withdrawal performance would materially change the risk call.","value":"Reserve disclosure and withdrawal performance would materially change the risk call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bitmart:controls","source:bitmart:closure"],"evidence_locator":"Current disclosure gap and user exit process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Final customer claims and BMX treatment remain unknown.","value":"Final customer claims and BMX treatment remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bitmart:closure","source:bitmart:bmx"],"evidence_locator":"No final closure accounting or token resolution is published.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:metric:breach-estimate","field_path":"metrics[metric:bitmart:breach-estimate:2021-12-05].value","assertion":"Independent 2021 breach loss estimate was 196000000 USD for the stated scope and date.","value":196000000,"as_of":"2021-12-05","confidence":"high","kind":"fact","source_ids":["source:bitmart:breach-independent","source:bitmart:breach"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:event:breach","field_path":"events[event:bitmart:breach]","assertion":"BitMart reported a stolen private key affecting two hot wallets and said it would compensate affected users.","value":"2021-12-05","as_of":"2021-12-05","confidence":"high","kind":"fact","source_ids":["source:bitmart:breach"],"evidence_locator":"Operator incident update.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:event:account-controls","field_path":"events[event:bitmart:account-controls]","assertion":"BitMart described restrictions on 239 linked accounts and said proof of reserves was not yet published.","value":"2026-05-23","as_of":"2026-05-23","confidence":"high","kind":"fact","source_ids":["source:bitmart:controls"],"evidence_locator":"Operator controls statement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bitmart:event:wind-down","field_path":"events[event:bitmart:wind-down]","assertion":"BitMart announced its phased cessation schedule.","value":"2026-07-26","as_of":"2026-07-26","confidence":"high","kind":"fact","source_ids":["source:bitmart:closure","source:bitmart:coindesk-close"],"evidence_locator":"Operator announcement and independent coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:15:00Z","next_review_at":"2026-08-10T21:15:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Audited wind-down balance sheet","Decision-maker record","Withdrawal service-level data","Post-closure BMX utility"]},"extensions":{"legacy_origin":"dead_exchanges","identity_boundary":"This profile covers the BitMart custodial exchange and its announced wind-down. BMX is a separate token, the 2021 hot-wallet breach is a historical incident, and account restrictions reported in May 2026 do not by themselves prove the cause of the July closure.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, reserve snapshots and tokens are kept separate.","The operator gave broad market and strategy reasons but no audited causal account; this report does not invent one.","The 58% BMX move is an event-window market observation, not a permanent holder loss or a measure of exchange liabilities."],"explicit_unknowns":["Financial condition and liabilities during the wind-down","Specific board or owner decision process behind closure","Withdrawal completion rate and latency","Treatment of remaining BMX utility after platform closure"]}}', '{"kind":"cex","slug":"bitmart","lifecycle":"dead","operating_model":"Custodial multi-product exchange executing a phased platform wind-down.","product_cohort":"centralized_multi_product_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"BMX","token_launch_date":null,"token_launch_timing":"at_or_near_launch","token_strategy":"exchange_utility_fee_repurchases_and_burns","token_source_url":"https://www.bitmart.com/en-US/support/articles/7949433565211/360000415634/360003185273","metric_type":"customer_shortfall","metric_unit":"usd","metric_window":"historical_incident_estimate","metric_as_of":"2021-12-05","metric_observed_at":"2026-08-03T21:15:00Z","comparability_key":"cex|centralized_multi_product_exchange|customer_shortfall|usd|incident_estimate","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers the BitMart custodial exchange and its announced wind-down. BMX is a separate token, the 2021 hot-wallet breach is a historical incident, and account restrictions reported in May 2026 do not by themselves prove the cause of the July closure.","source_count":7},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_e_profiles_0095 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'htx', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:htx","type":"cex","slug":"htx","name":"HTX","aliases":["Huobi","Huobi Global"]},"classification":{"subtype":"custodial multi-product exchange with disputed legal-entity perimeter","tags":["custodial","spot","derivatives","sanctions","legal-proceedings","exchange-token"],"chains":[],"jurisdictions":["global","United Kingdom"]},"status":{"operating_state":"operating_high_risk","as_of":"2026-08-03","claim_ids":["claim:htx:status"]},"outcome":{"label":"operating_regulatory_and_identity_risk","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:htx:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"HTX is the rebranded Huobi exchange, offering custodial spot, derivatives and related services. Its public agreement defines “HTX Operators” broadly and tells users that the relevant counterparty can vary by service. That flexibility is now a core risk rather than a drafting footnote because UK authorities named Huobi Global S.A. and say the HTX exchange is covered, while HTX says the online exchange is separate.","as_of":"2026-08-03","claim_ids":["claim:htx:section:what_it_is:1","claim:htx:section:what_it_is:2","claim:htx:section:what_it_is:3"]},"what_happened":{"body":"The FCA began High Court proceedings over allegedly illegal UK financial promotions and updated its service orders in June 2026. On May 26 the UK designated Huobi Global S.A. under Russia sanctions, and OFSI later said the HTX exchange was subject to those restrictions through ownership and control. HTX publicly rejected the entity connection. The dispute has not stopped the global site from publishing current terms, token benefits and reserve snapshots.","as_of":"2026-08-03","claim_ids":["claim:htx:section:what_happened:1","claim:htx:section:what_happened:2","claim:htx:section:what_happened:3"]},"why_this_outcome":{"body":"HTX preserved a large global product surface by using a flexible operator structure and moving the brand beyond Huobi, but the same opacity makes legal and regulatory perimeter questions harder to resolve. The UK dispute is therefore not just external enforcement; it exposes a strategic tradeoff between jurisdictional flexibility and customer certainty about who holds assets and owes obligations. Continued operation shows resilience, not resolution.","as_of":"2026-08-03","claim_ids":["claim:htx:section:why_this_outcome:1","claim:htx:section:why_this_outcome:2","claim:htx:section:why_this_outcome:3"]},"strategic_choices":{"body":"HTX chose a multi-product global model, a rebrand away from Huobi, a broad operator definition and a token-led loyalty system. It also answers trust questions with recurring Merkle reserve reports rather than a public consolidated audit. Those choices support speed and customer incentives but concentrate confidence in changing contracts, operator assertions and jurisdiction-by-jurisdiction access. The UK episode shows the cost when authorities apply a wider control test.","as_of":"2026-08-03","claim_ids":["claim:htx:section:strategic_choices:1","claim:htx:section:strategic_choices:2","claim:htx:section:strategic_choices:3"]},"operating_model":{"body":"HTX holds customer assets, matches trades and offers products through legal persons or other operators that can differ by service. Customers depend on the platform ledger, custody controls and withdrawal process. The June reserve page reported asset-specific ratios above 100%, but the methodology is a point-in-time Merkle comparison and may include third-party custody. It does not publish consolidated revenue, operating costs or a complete audited liability perimeter.","as_of":"2026-08-03","claim_ids":["claim:htx:section:operating_model:1","claim:htx:section:operating_model:2","claim:htx:section:operating_model:3"]},"token_and_value_capture":{"body":"HTX migrated exchange benefits toward the HTX token, which is promoted for fee discounts, governance and membership. HTX DAO reports periodic burns, including a Q1 2026 burn valued by the publisher at about $19.22 million. That design can connect activity to token scarcity, but burn-value figures are operator or DAO claims and do not grant holders ownership of the exchange, customer assets or regulated-entity cash flow.","as_of":"2026-08-03","claim_ids":["claim:htx:section:token_and_value_capture:1","claim:htx:section:token_and_value_capture:2","claim:htx:section:token_and_value_capture:3"]},"counterfactual":{"body":"A single named customer-facing legal entity, a published service-to-entity map and audited consolidated liabilities would have reduced the ambiguity now driving the UK dispute. HTX might still have faced sanctions or promotion rules, but users and counterparties could more easily identify the responsible company. A narrower jurisdictional footprint could lower enforcement exposure, while also sacrificing volume and distribution. Public evidence cannot price that tradeoff.","as_of":"2026-08-03","claim_ids":["claim:htx:section:counterfactual:1","claim:htx:section:counterfactual:2","claim:htx:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The largest risks are sanctions compliance, the FCA case, uncertain customer counterparties, custody and token dependence. HTX says the designated company is separate; OFSI says the exchange is covered. That contradiction must remain visible until a court, regulator or authoritative entity map resolves it. Reserve ratios can help customers verify inclusion at a snapshot, but they do not prove solvency, beneficial ownership or access to every custodian wallet.","as_of":"2026-08-03","claim_ids":["claim:htx:section:risks_and_unknowns:1","claim:htx:section:risks_and_unknowns:2","claim:htx:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Huobi grew into a major global exchange, rebranded to HTX and shifted platform incentives toward a new HTX token. A November 2023 security incident added custody history. By 2026 the defining phase was regulatory: FCA proceedings, a UK designation and a public fight over whether Huobi Global S.A. and the online exchange sit inside the same perimeter. The venue remains online, but its lifecycle has moved from expansion to high-risk regulatory adaptation.","as_of":"2026-08-03","claim_ids":["claim:htx:section:lifecycle:1","claim:htx:section:lifecycle:2","claim:htx:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch the FCA docket, sanctions guidance, app and payment access, named contracting entities, reserve methodology, withdrawal performance and HTX-token burns. The call improves if HTX publishes a stable legal-entity map, independent assurance and clean regulator outcomes. It worsens if more counterparties block access, courts reject the separation argument or customers cannot identify who owes them assets. Continued web access alone is not a sufficient health signal.","as_of":"2026-08-03","claim_ids":["claim:htx:section:outlook_and_watch:1","claim:htx:section:outlook_and_watch:2","claim:htx:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:htx:btc-reserve-ratio:2026-06-01","dimension":"reserve_coverage","label":"BTC reserve ratio","value":103,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2026-06-01","definition":"point-in-time snapshot"},"as_of":"2026-06-01","method":"Operator-reported Merkle snapshot.","scope":{"product":"HTX disclosed BTC wallets and user balances","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:htx:metric:btc-reserve-ratio"],"quality_flags":["operator_reported","snapshot","not_financial_statement_audit","liability_completeness_not_verified"]},{"id":"metric:htx:stablecoin-reserve-ratio:2026-06-01","dimension":"reserve_coverage","label":"Disclosed USD-stablecoin reserve ratio","value":104,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2026-06-01","definition":"point-in-time snapshot"},"as_of":"2026-06-01","method":"Operator-reported grouped stablecoin snapshot.","scope":{"product":"HTX disclosed stablecoin wallets and user balances","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:htx:metric:stablecoin-reserve-ratio"],"quality_flags":["operator_reported","snapshot","grouped_assets","not_financial_statement_audit"]}],"events":[{"id":"event:htx:fca-proceedings","type":"legal","date":"2026-02-10","description":"The FCA announced High Court proceedings over alleged illegal financial promotions.","claim_ids":["claim:htx:event:fca-proceedings"]},{"id":"event:htx:uk-designation","type":"sanctions","date":"2026-05-26","description":"The UK designated Huobi Global S.A. under Russia sanctions.","claim_ids":["claim:htx:event:uk-designation"]},{"id":"event:htx:entity-dispute","type":"legal_response","date":"2026-05-27","description":"HTX disputed that the designated entity represented the online exchange.","claim_ids":["claim:htx:event:entity-dispute"]}],"sources":[{"id":"source:htx:fca-case","title":"HTX (Huobi): legal proceedings","url":"https://www.fca.org.uk/news/statements/htx-huobi-legal-proceedings","publisher":"UK Financial Conduct Authority","published_at":"2026-06-29","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current High Court service orders and named Huobi Global S.A. proceeding.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:fca-release","title":"FCA takes action against HTX over illegal financial promotions","url":"https://www.fca.org.uk/news/press-releases/fca-action-against-htx-illegal-financial-promotions","publisher":"UK Financial Conduct Authority","published_at":"2026-02-10","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Regulator allegation, prior warning and UK consumer-access restrictions.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:sanctions","title":"UK sanctions designation: Huobi Global S.A.","url":"https://search-uk-sanctions-list.service.gov.uk/designations/RUS3619/Entity","publisher":"UK Sanctions List","published_at":"2026-05-26","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Named designated entity, date, asset-freeze measures and statement of reasons.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:ofsi","title":"UK financial sanctions FAQs","url":"https://www.gov.uk/government/publications/uk-financial-sanctions-faqs/uk-financial-sanctions-faqs","publisher":"UK Office of Financial Sanctions Implementation","published_at":"2026-05-29","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"FAQ 186 treatment of the HTX exchange under ownership-and-control rules.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:response","title":"HTX response regarding the UK sanctions designation","url":"https://www.htx.com/fr-fr/support/65034152911363/","publisher":"HTX","published_at":"2026-05-27","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Operator assertion that Huobi Global S.A. is separate from the online HTX exchange.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:agreement","title":"HTX user agreement","url":"https://www.htx.com/en-in/support/360000298561","publisher":"HTX","published_at":"2026-06-18","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Definition of HTX Operators and user counterparty-identification language.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:por","title":"HTX proof of reserves","url":"https://www.htx.com/en-us/proof-of-reserve","publisher":"HTX","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current Merkle-tree reserve methodology, 1:1 operator claim and third-party custody caveat.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:june-por","title":"HTX June 2026 proof-of-reserves report","url":"https://square.htx.com/htx-releases-june-2026-merkle-tree-proof-of-reserves-2/","publisher":"HTX Square","published_at":"2026-06-01","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"June 1 snapshot reserve ratios for BTC, ETH, stablecoins and selected assets.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:token-convert","title":"HTX token conversion and benefits","url":"https://www.htx.com/en-us/htx/convert","publisher":"HTX","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current HTX-token governance, fee-discount and membership benefits.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:burn","title":"HTX DAO completes Q1 2026 HTX burn","url":"https://square.htx.com/htx-dao-completes-q1-2026-htx-burn-two-year-supply-shrinks-over-11-as-deflation-accelerates/","publisher":"HTX Square","published_at":"2026-04-15","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Operator/DAO-reported quarterly and cumulative burn amounts.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:htx:eu-observatory","title":"EU Blockchain Observatory November 2023 trends report","url":"https://blockchain-observatory.ec.europa.eu/document/download/a337a52d-ed31-42ee-9122-63db5c8eafe3_en?filename=November+2023+Trends+Report.pdf","publisher":"EU Blockchain Observatory and Forum","published_at":"2023-11-30","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent summary of the November 2023 HTX security incident and reported loss.","direct_http_status":200,"access_method":"direct_pdf"}],"claims":[{"id":"claim:htx:status","field_path":"status.operating_state","assertion":"HTX remained an online operating exchange at the review date while facing UK legal proceedings and sanctions-related restrictions.","value":"operating_high_risk","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:agreement","source:htx:por","source:htx:fca-case","source:htx:ofsi"],"evidence_locator":"Current operator terms and reserve page together with live regulator and sanctions records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:outcome","field_path":"outcome.label","assertion":"HTX is classified as operating with high regulatory and legal-entity risk, not as closed.","value":"operating_regulatory_and_identity_risk","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:fca-case","source:htx:sanctions","source:htx:ofsi","source:htx:response","source:htx:agreement"],"evidence_locator":"The venue still publishes current terms and reserves, while official UK records and the operator disagree about the entity perimeter.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"HTX offers custodial exchange services under a broad operator definition.","value":"HTX offers custodial exchange services under a broad operator definition.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:agreement","source:htx:por"],"evidence_locator":"Current terms and reserve methodology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"UK authorities named Huobi Global S.A. and addressed the HTX exchange.","value":"UK authorities named Huobi Global S.A. and addressed the HTX exchange.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:sanctions","source:htx:ofsi"],"evidence_locator":"Official designation and FAQ.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"HTX disputes that Huobi Global S.A. represents the online exchange.","value":"HTX disputes that Huobi Global S.A. represents the online exchange.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:response"],"evidence_locator":"Operator response.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"The FCA brought High Court proceedings concerning UK financial promotions.","value":"The FCA brought High Court proceedings concerning UK financial promotions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:fca-case","source:htx:fca-release"],"evidence_locator":"Regulator case and press release.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Huobi Global S.A. was designated on May 26, 2026.","value":"Huobi Global S.A. was designated on May 26, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:sanctions"],"evidence_locator":"Official sanctions record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"OFSI and HTX published conflicting positions on whether the online exchange is covered.","value":"OFSI and HTX published conflicting positions on whether the online exchange is covered.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:ofsi","source:htx:response"],"evidence_locator":"Official FAQ and operator response.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"HTX terms allow operators and counterparties to vary by service.","value":"HTX terms allow operators and counterparties to vary by service.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:agreement"],"evidence_locator":"Current user-agreement definitions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"That flexibility reduces legal-entity clarity for users.","value":"That flexibility reduces legal-entity clarity for users.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:agreement","source:htx:ofsi","source:htx:response"],"evidence_locator":"Analyst inference from conflicting official and operator positions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Current operation does not resolve the FCA case or sanctions dispute.","value":"Current operation does not resolve the FCA case or sanctions dispute.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:por","source:htx:fca-case","source:htx:sanctions"],"evidence_locator":"Operating and legal records remain separate.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"HTX uses a broad multi-operator contractual structure.","value":"HTX uses a broad multi-operator contractual structure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:agreement"],"evidence_locator":"User agreement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"HTX chose recurring Merkle reserve disclosures.","value":"HTX chose recurring Merkle reserve disclosures.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:por","source:htx:june-por"],"evidence_locator":"Current methodology and June snapshot.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"HTX tied customer benefits to the HTX token.","value":"HTX tied customer benefits to the HTX token.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:token-convert","source:htx:burn"],"evidence_locator":"Current token benefits and burn report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"The customer counterparty can vary according to the service.","value":"The customer counterparty can vary according to the service.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:agreement"],"evidence_locator":"Operator-definition and service terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"The June snapshot reported selected asset ratios at or above 100%.","value":"The June snapshot reported selected asset ratios at or above 100%.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:june-por"],"evidence_locator":"Operator-reported snapshot.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"The reserve page is not a consolidated financial-statement audit.","value":"The reserve page is not a consolidated financial-statement audit.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:por","source:htx:june-por"],"evidence_locator":"Method and scope limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"HTX token is promoted for discounts, governance and membership benefits.","value":"HTX token is promoted for discounts, governance and membership benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:token-convert"],"evidence_locator":"Current benefits page.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"HTX DAO reported a Q1 2026 burn valued at about $19.22 million.","value":"HTX DAO reported a Q1 2026 burn valued at about $19.22 million.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:htx:burn"],"evidence_locator":"DAO/operator report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Those token benefits do not establish equity or customer-asset rights.","value":"Those token benefits do not establish equity or customer-asset rights.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:token-convert","source:htx:agreement"],"evidence_locator":"Token and customer-contract boundary.","support_direction":"supports","note":null,