","source_ids":["source:htx:eu-observatory"],"evidence_locator":"Independent historical incident summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"The 2026 lifecycle is operating under regulatory and entity-perimeter pressure.","value":"The 2026 lifecycle is operating under regulatory and entity-perimeter pressure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:fca-case","source:htx:sanctions","source:htx:response"],"evidence_locator":"Analyst classification from current records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"FCA and sanctions records are direct legal milestones to monitor.","value":"FCA and sanctions records are direct legal milestones to monitor.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:fca-case","source:htx:sanctions","source:htx:ofsi"],"evidence_locator":"Current official records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Entity maps and independent assurance would change the risk call.","value":"Entity maps and independent assurance would change the risk call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:htx:agreement","source:htx:por"],"evidence_locator":"Current identity and assurance gaps.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Future access restrictions and legal outcomes are unknown.","value":"Future access restrictions and legal outcomes are unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:htx:fca-case","source:htx:sanctions"],"evidence_locator":"Open proceedings and implementation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:metric:btc-reserve-ratio","field_path":"metrics[metric:htx:btc-reserve-ratio:2026-06-01].value","assertion":"BTC reserve ratio was 103 PERCENT for the stated scope and date.","value":103,"as_of":"2026-06-01","confidence":"high","kind":"fact","source_ids":["source:htx:june-por"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:metric:stablecoin-reserve-ratio","field_path":"metrics[metric:htx:stablecoin-reserve-ratio:2026-06-01].value","assertion":"Disclosed USD-stablecoin reserve ratio was 104 PERCENT for the stated scope and date.","value":104,"as_of":"2026-06-01","confidence":"high","kind":"fact","source_ids":["source:htx:june-por"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:event:fca-proceedings","field_path":"events[event:htx:fca-proceedings]","assertion":"The FCA announced High Court proceedings over alleged illegal financial promotions.","value":"2026-02-10","as_of":"2026-02-10","confidence":"high","kind":"fact","source_ids":["source:htx:fca-release","source:htx:fca-case"],"evidence_locator":"Official regulator record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:event:uk-designation","field_path":"events[event:htx:uk-designation]","assertion":"The UK designated Huobi Global S.A. under Russia sanctions.","value":"2026-05-26","as_of":"2026-05-26","confidence":"high","kind":"fact","source_ids":["source:htx:sanctions"],"evidence_locator":"Official designation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:htx:event:entity-dispute","field_path":"events[event:htx:entity-dispute]","assertion":"HTX disputed that the designated entity represented the online exchange.","value":"2026-05-27","as_of":"2026-05-27","confidence":"high","kind":"fact","source_ids":["source:htx:response","source:htx:ofsi"],"evidence_locator":"Operator response and later OFSI interpretation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:15:00Z","next_review_at":"2026-08-10T21:15:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["Product-by-product legal-entity map","Final FCA judgment","Global sanctions implementation","Audited consolidated reserves"]},"extensions":{"legacy_origin":"mid_exchanges","identity_boundary":"Huobi Global S.A., the online HTX exchange, unspecified “HTX Operators,” the HTX DAO and the HTX token are not interchangeable. UK authorities say ownership-and-control rules bring the exchange into scope; HTX disputes that reading. This report records both positions and does not decide the legal dispute.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, reserve snapshots and tokens are kept separate.","Sanctions and FCA proceedings are legal facts and allegations, not proof of insolvency.","Merkle reserve ratios are point-in-time operator disclosures, not audited financial statements or proof that every liability is included."],"explicit_unknowns":["The precise legal counterparty for every customer and product","Final outcome of FCA proceedings","Practical effect of UK sanctions across jurisdictions and counterparties","Audited consolidated customer assets and liabilities"]}}', '{"kind":"cex","slug":"htx","lifecycle":"mid","operating_model":"Custodial multi-product exchange whose customer counterparty can vary across HTX Operators and services.","product_cohort":"centralized_multi_product_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"HTX","token_launch_date":null,"token_launch_timing":"post_product","token_strategy":"exchange_utility_governance_fee_discounts_and_burns","token_source_url":"https://www.htx.com/en-us/htx/convert","metric_type":"reserve_coverage","metric_unit":"percent","metric_window":"point_in_time_snapshot","metric_as_of":"2026-06-01","metric_observed_at":"2026-08-03T21:15:00Z","comparability_key":"cex|centralized_multi_product_exchange|reserve_coverage|percent|snapshot","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"Huobi Global S.A., the online HTX exchange, unspecified “HTX Operators,” the HTX DAO and the HTX token are not interchangeable. UK authorities say ownership-and-control rules bring the exchange into scope; HTX disputes that reading. This report records both positions and does not decide the legal dispute.","source_count":11},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_e_profiles_0095 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'kucoin', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:kucoin","type":"cex","slug":"kucoin","name":"KuCoin","aliases":["KuCoin Exchange","Peken Global Limited"]},"classification":{"subtype":"custodial global multi-product exchange under regulatory remediation","tags":["custodial","spot","derivatives","guilty-plea","european-remediation","exchange-token"],"chains":[],"jurisdictions":["global","United States","European Union","Austria"]},"status":{"operating_state":"operating_under_remediation","as_of":"2026-08-03","claim_ids":["claim:kucoin:status"]},"outcome":{"label":"operating_after_us_conviction_with_eu_launch_blocked","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:kucoin:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"KuCoin is a custodial global exchange offering spot, margin, futures and related services, with KCS used for fee discounts and other platform benefits. The brand spans multiple legal entities. That distinction matters: Peken Global Limited is the company that pleaded guilty in the United States, while KuCoin EU Exchange GmbH holds an Austrian authorization but is still prohibited from commencing business there.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:what_it_is:1","claim:kucoin:section:what_it_is:2","claim:kucoin:section:what_it_is:3"]},"what_happened":{"body":"In January 2025 Peken Global pleaded guilty to unlicensed money transmission, agreed to more than $297 million in forfeiture and fines, left the U.S. market for at least two years and changed management. Austria later authorized KuCoin EU under MiCA, but the FMA restricted new business over governance and compliance staffing. In May 2026 the FMA lifted that narrow ban while keeping the more important prohibition on starting operations.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:what_happened:1","claim:kucoin:section:what_happened:2","claim:kucoin:section:what_happened:3"]},"why_this_outcome":{"body":"KuCoin grew through a broad global product set, low-friction access and token-linked incentives, but compliance systems and jurisdictional boundaries did not keep pace with that distribution. The U.S. conviction converted that gap into a costly exit and governance reset. The Austrian sequence shows that obtaining a licence is not enough when required management and control functions are unfinished. Global continuity reflects product demand; it does not erase entity-specific failures.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:why_this_outcome:1","claim:kucoin:section:why_this_outcome:2","claim:kucoin:section:why_this_outcome:3"]},"strategic_choices":{"body":"KuCoin chose rapid multi-jurisdiction expansion, a wide spot-and-derivatives menu and KCS-based fee incentives. After enforcement, it accepted a U.S. exit and management changes while pursuing a regulated European entity. That is a pivot from border-light growth toward licensed regional operations, but the Austrian launch block shows the execution is incomplete. The strategy can work only if governance capacity matches the number of products and legal entities.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:strategic_choices:1","claim:kucoin:section:strategic_choices:2","claim:kucoin:section:strategic_choices:3"]},"operating_model":{"body":"Customers deposit assets with KuCoin and trade through its internal custodial ledger across spot and derivatives products. Fees are discounted for qualifying KCS use. KuCoin publishes Merkle proof-of-reserves ratios, including a June 30, 2026 snapshot above 100% for four major assets. Those ratios compare disclosed wallets and user balances at one moment; they do not show revenue, capital, off-balance-sheet obligations or the full legal owner of every wallet.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:operating_model:1","claim:kucoin:section:operating_model:2","claim:kucoin:section:operating_model:3"]},"token_and_value_capture":{"body":"KCS reduces eligible trading fees and is tied to a supply-reduction plan that began from a stated 200 million tokens with a target of 100 million. That design lets activity and platform loyalty support the token, while exchange fees remain corporate revenue. KCS is not equity in KuCoin or a claim on customer reserves. Public token burns also do not prove that the underlying venue is profitable or that regulators accept the product.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:token_and_value_capture:1","claim:kucoin:section:token_and_value_capture:2","claim:kucoin:section:token_and_value_capture:3"]},"counterfactual":{"body":"Earlier U.S. registration, stronger AML controls and a clearer entity map could have avoided or reduced the guilty plea and forced exit. In Austria, filling required governance roles before seeking launch would have reduced delay. A narrower product or country footprint might have been easier to supervise, but public data do not show whether the sacrificed volume would outweigh compliance cost. The useful test is durable legal access, not maximum short-term reach.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:counterfactual:1","claim:kucoin:section:counterfactual:2","claim:kucoin:section:counterfactual:3"]},"risks_and_unknowns":{"body":"KuCoin’s main risks are recurring compliance failures, fragmented legal entities, custody, derivatives exposure and KCS dependence. The U.S. plea is completed, but the Austrian entity still cannot commence business. Reserve ratios provide a useful snapshot and customer verification path, yet liability completeness and group-wide capital remain unaudited in the reviewed record. Customers should identify their contracting entity rather than assuming every KuCoin service has the same protections.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:risks_and_unknowns:1","claim:kucoin:section:risks_and_unknowns:2","claim:kucoin:section:risks_and_unknowns:3"]},"lifecycle":{"body":"KuCoin scaled from a global crypto venue into a large multi-product exchange with its own token. State and federal U.S. actions culminated in customer refunds, penalties, a guilty plea and a market exit. The next phase is regional licensing: Austria granted authorization, then held back business commencement until governance conditions are met. The global venue remains online, making the lifecycle one of constrained adaptation rather than closure or clean regulatory success.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:lifecycle:1","claim:kucoin:section:lifecycle:2","claim:kucoin:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch whether KuCoin EU satisfies the FMA, whether any further jurisdictions restrict service, whether legal entities become easier to identify, and whether reserve reports gain independent assurance. The call improves if the Austrian business starts lawfully, controls remain staffed and no new enforcement follows. It worsens if governance gaps recur or the global brand keeps relying on entity ambiguity. KCS price and burns are secondary to durable access and customer-asset protection.","as_of":"2026-08-03","claim_ids":["claim:kucoin:section:outlook_and_watch:1","claim:kucoin:section:outlook_and_watch:2","claim:kucoin:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:kucoin:us-penalties:2025-01-27","dimension":"regulatory_fines","label":"U.S. forfeiture and criminal fine","value":297400000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2025-01-27","definition":"criminal disposition"},"as_of":"2025-01-27","method":"Sum of $184.5 million forfeiture and $112.9 million fine stated by DOJ.","scope":{"product":"Peken Global Limited","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kucoin:metric:us-penalties"],"quality_flags":["includes_forfeiture_and_fine","specific_legal_entity","not_global_kucoin_revenue"]},{"id":"metric:kucoin:btc-reserve-ratio:2026-06-30","dimension":"reserve_coverage","label":"BTC reserve ratio","value":111,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2026-06-30","definition":"point-in-time snapshot"},"as_of":"2026-06-30","method":"Operator-reported June 30 Merkle snapshot.","scope":{"product":"KuCoin disclosed BTC wallets and user balances","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kucoin:metric:btc-reserve-ratio"],"quality_flags":["operator_reported","snapshot","not_financial_statement_audit"]},{"id":"metric:kucoin:usdt-reserve-ratio:2026-06-30","dimension":"reserve_coverage","label":"USDT reserve ratio","value":119,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2026-06-30","definition":"point-in-time snapshot"},"as_of":"2026-06-30","method":"Operator-reported June 30 Merkle snapshot.","scope":{"product":"KuCoin disclosed USDT wallets and user balances","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:kucoin:metric:usdt-reserve-ratio"],"quality_flags":["operator_reported","snapshot","not_financial_statement_audit"]}],"events":[{"id":"event:kucoin:new-york-settlement","type":"legal","date":"2023-12-12","description":"KuCoin agreed to customer refunds, a state penalty and an exit from New York.","claim_ids":["claim:kucoin:event:new-york-settlement"]},{"id":"event:kucoin:guilty-plea","type":"legal","date":"2025-01-27","description":"Peken Global pleaded guilty and accepted penalties, a U.S. exit and management changes.","claim_ids":["claim:kucoin:event:guilty-plea"]},{"id":"event:kucoin:eu-launch-block","type":"regulatory","date":"2026-05-18","description":"The FMA lifted a new-business ban but kept KuCoin EU prohibited from commencing operations.","claim_ids":["claim:kucoin:event:eu-launch-block"]}],"sources":[{"id":"source:kucoin:doj-plea","title":"KuCoin pleads guilty to unlicensed money transmission charge","url":"https://www.justice.gov/usao-sdny/pr/kucoin-pleads-guilty-unlicensed-money-transmission-charge