or":"Current identity and assurance gaps.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kucoin:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Timing of Austrian commencement and future enforcement are unknown.","value":"Timing of Austrian commencement and future enforcement are unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:kucoin:fma-current"],"evidence_locator":"Open regulatory conditions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kucoin:metric:us-penalties","field_path":"metrics[metric:kucoin:us-penalties:2025-01-27].value","assertion":"U.S. forfeiture and criminal fine was 297400000 USD for the stated scope and date.","value":297400000,"as_of":"2025-01-27","confidence":"high","kind":"fact","source_ids":["source:kucoin:doj-plea","source:kucoin:reuters"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kucoin:metric:btc-reserve-ratio","field_path":"metrics[metric:kucoin:btc-reserve-ratio:2026-06-30].value","assertion":"BTC reserve ratio was 111 PERCENT for the stated scope and date.","value":111,"as_of":"2026-06-30","confidence":"high","kind":"fact","source_ids":["source:kucoin:por"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:kucoin:metric:usdt-reserve-ratio","field_path":"metrics[metric:kucoin:usdt-reserve-ratio:2026-