_review_at":"2026-08-10T21:15:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Segment profitability","Complete entity map","Austrian launch date","Audited consolidated liability coverage"]},"extensions":{"legacy_origin":"mid_exchanges","identity_boundary":"Peken Global Limited pleaded guilty in the United States. KuCoin EU Exchange GmbH is the Austrian MiCA entity whose business start remains prohibited. Other entities named in the 2024 charges and the global KuCoin brand must not be treated as the same legal person without a source.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, reserve snapshots and tokens are kept separate.","A MiCA authorization and a later prohibition on commencing business are both true; the later FMA notice controls the current Austrian operating call.","Proof-of-reserves ratios are point-in-time operator disclosures, not audited proof of consolidated solvency."],"explicit_unknowns":["Current global revenue and profitability by product","Complete service-to-legal-entity map","When or whether KuCoin EU may commence business","Audited completeness of customer liabilities behind proof of reserves"]}}', '{"kind":"cex","slug":"kucoin","lifecycle":"mid","operating_model":"Custodial global spot and derivatives exchange operating through multiple legal entities.","product_cohort":"centralized_multi_product_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"KCS","token_launch_date":null,"token_launch_timing":"post_product","token_strategy":"exchange_utility_fee_discounts_and_burns","token_source_url":"https://www.kucoin.com/en-au/support/47497300094040","metric_type":"reserve_coverage","metric_unit":"percent","metric_window":"point_in_time_snapshot","metric_as_of":"2026-06-30","metric_observed_at":"2026-08-03T21:15:00Z","comparability_key":"cex|centralized_multi_product_exchange|reserve_coverage|percent|snapshot","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"Peken Global Limited pleaded guilty in the United States. KuCoin EU Exchange GmbH is the Austrian MiCA entity whose business start remains prohibited. Other entities named in the 2024 charges and the global KuCoin brand must not be treated as the same legal person without a source.","source_count":9},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_e_profiles_0095 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'bithumb', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:bithumb","type":"cex","slug":"bithumb","name":"Bithumb","aliases":["Bithumb Korea"]},"classification":{"subtype":"Korean-won custodial spot exchange","tags":["custodial","spot","krw","internal-controls","domestic-concentration"],"chains":[],"jurisdictions":["South Korea"]},"status":{"operating_state":"operating_under_control_remediation","as_of":"2026-08-03","claim_ids":["claim:bithumb:status"]},"outcome":{"label":"operating_domestic_leader_with_control_failure","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:bithumb:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Bithumb is a South Korean custodial exchange centered on won-denominated spot trading. Customers rely on Bithumb’s internal ledger, custody and banking access rather than settling every trade directly on-chain. Its strength is concentrated domestic distribution, not a broad global derivatives franchise. That same concentration makes Korean regulation, bank relationships, fee competition and operating controls unusually important to the business.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:what_it_is:1","claim:bithumb:section:what_it_is:2","claim:bithumb:section:what_it_is:3"]},"what_happened":{"body":"On February 6, 2026 a rewards-processing error credited customers with a combined 620,000 BTC on Bithumb’s internal system. The operator said it recovered 618,212 BTC of those credits, or 99.7%, while regulators began checking ledger integrity, sales and compensation. In April the FSC said inspections found internal-control deficiencies and that sanctions would be considered after legal review. The exchange continued operating.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:what_happened:1","claim:bithumb:section:what_happened:2","claim:bithumb:section:what_happened:3"]},"why_this_outcome":{"body":"Bithumb’s domestic brand, won market and promotional pricing preserved meaningful market share, but rapid operational campaigns ran through controls that failed on an extraordinary scale. The February event was not a blockchain exploit; it was a software-and-ledger governance failure. Regulators and users therefore have to judge the process that approved rewards, the ability to reverse mistaken credits and the company’s capacity to prevent a repeat—not just whether most entries were recovered.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:why_this_outcome:1","claim:bithumb:section:why_this_outcome:2","claim:bithumb:section:why_this_outcome:3"]},"strategic_choices":{"body":"Bithumb chose to compete aggressively in a concentrated Korean spot market with fee waivers and promotional rewards, while also pursuing an IPO. Those choices can win volume and brand attention, but they raise the cost of operational mistakes when reward logic and internal approvals are weak. After the error, the company emphasized recovery and compensation; regulators shifted attention to control design, and independent reporting linked the incident to renewed IPO and governance uncertainty.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:strategic_choices:1","claim:bithumb:section:strategic_choices:2","claim:bithumb:section:strategic_choices:3"]},"operating_model":{"body":"Bithumb takes custody of customer assets, maintains account balances and matches won-denominated spot trades on an internal ledger. Its economic engine is trading activity and related fees, shaped by competition with Upbit and access to Korean banking rails. Temporary fee waivers can raise market share while reducing immediate fee capture. Public corporate reports provide company-level financial history, but the reviewed record does not provide a current audited reserve-to-customer-liability ratio.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:operating_model:1","claim:bithumb:section:operating_model:2","claim:bithumb:section:operating_model:3"]},"token_and_value_capture":{"body":"The reviewed current Bithumb corporate, regulatory and incident sources do not identify a live Bithumb venue token that gives users exchange ownership or a fee claim. Value capture therefore appears to sit in the operating company’s trading economics and, if an IPO eventually occurs, its corporate securities—not an exchange-token market. This is a bounded research finding, not proof that no promotional or historical token has ever used the name.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:token_and_value_capture:1","claim:bithumb:section:token_and_value_capture:2","claim:bithumb:section:token_and_value_capture:3"]},"counterfactual":{"body":"Stronger change control, staged reward deployment, hard balance ceilings and independent reconciliation could have prevented or contained the erroneous credits before they reached customer accounts. A less aggressive promotion might also have reduced operational pressure, though the evidence does not show that marketing speed directly caused the bug. For the business, a credible controls reset before reviving the IPO would matter more than another short fee campaign.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:counterfactual:1","claim:bithumb:section:counterfactual:2","claim:bithumb:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The key risks are internal ledger integrity, governance accountability, final sanctions, domestic concentration and custody. Bithumb says it recovered nearly all erroneous entries, but that is not the same as a final audited loss number or proof that no customer was harmed. Market share around the mid-20s after fee waivers ended shows a large franchise, yet it remains an estimate from one domestic period. The final IPO and control consequences remain open.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:risks_and_unknowns:1","claim:bithumb:section:risks_and_unknowns:2","claim:bithumb:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Bithumb grew into one of South Korea’s two dominant exchanges through domestic brand recognition, won trading and aggressive fee competition. It completed the country’s VASP reporting process in 2021 and continued pursuing public-market ambitions. The 2026 rewards error exposed how much trust depends on the internal ledger and governance. Its current phase is continued operation under scrutiny, with the recovery claim strong enough to avoid a collapse label but not enough to close the case.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:lifecycle:1","claim:bithumb:section:lifecycle:2","claim:bithumb:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch the final FSC sanctions, audited incident cost, control changes, customer complaints, Korean market share, banking access and the IPO timetable. The call improves if Bithumb publishes a clear root-cause review, independent assurance and sustained share without uneconomic fee waivers. It worsens if another ledger failure appears or regulators find deeper governance problems. Headline recovered BTC entries should never substitute for verified cash loss and customer-liability data.","as_of":"2026-08-03","claim_ids":["claim:bithumb:section:outlook_and_watch:1","claim:bithumb:section:outlook_and_watch:2","claim:bithumb:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:bithumb:domestic-share:2026-02-22","dimension":"market_share","label":"Approximate Korean spot-market share after fee waivers","value":25,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2026-02-22","definition":"post-incident observation"},"as_of":"2026-02-22","method":"Independent description of share in the mid-20% range after waivers ended.","scope":{"product":"South Korean crypto-exchange spot market","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bithumb:metric:domestic-share"],"quality_flags":["approximate_midpoint","independent_estimate","domestic_market_only","post_fee_waiver"]}],"events":[{"id":"event:bithumb:ledger-error","type":"operational_incident","date":"2026-02-06","description":"A rewards-processing error created 620,000 BTC of erroneous internal account credits.","claim_ids":["claim:bithumb:event:ledger-error"]},{"id":"event:bithumb:recovery-report","type":"operational_recovery","date":"2026-02-07","description":"Bithumb reported recovering 618,212 BTC of erroneous ledger credits.","claim_ids":["claim:bithumb:event:recovery-report"]},{"id":"event:bithumb:control-findings","type":"regulatory","date":"2026-04-06","description":"The FSC reported control deficiencies and a pending sanction-review process.","claim_ids":["claim:bithumb:event:control-findings"]}],"sources":[{"id":"source:bithumb:fsc-incident","title":"Financial authorities respond to Bithumb erroneous bitcoin payouts","url":"https://www.fsc.go.kr/eng/pr010101/86230?curPage=&srchBeginDt=&srchCtgry=5&srchEndDt=&srchKey=&srchText=","publisher":"South Korean Financial Services Commission","published_at":"2026-02-08","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Regulator confirmation of erroneous BTC payouts, compensation planning and ledger-accuracy review.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:fsc-controls","title":"FSC inspection findings on virtual-asset exchange internal controls","url":"https://www.fsc.go.kr/eng/pr010101/86638?curPage=&srchBeginDt=&srchCtgry=&srchEndDt=&srchKey=&srchText=","publisher":"South Korean Financial Services Commission","published_at":"2026-04-06","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Inspection findings concerning Bithumb controls and planned sanction-review process.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:operator-incident","title":"Bithumb notice on erroneous BTC credits","url":"https://feed.bithumb.com/notice/1651924","publisher":"Bithumb","published_at":"2026-02-07","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Operator-reported 620,000 BTC internal credits, 618,212 BTC recovery and 99.7% recovery ratio.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:bithumb:reports","title":"Bithumb Korea financial reports","url":"https://www.bithumbcorp.com/ko/company/report.php","publisher":"Bithumb Korea","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current corporate financial-report index and reporting-entity boundary.","direct_http_status":0,"access_method":"browser_rendered_page"},{"id":"source:bithumb:vasp","title":"Korean FIU accepts reports from three virtual-asset service providers","url":"https://www.fsc.go.kr/eng/pr010101/76569?curPage=14&srchBeginDt=&srchCtgry=3&srchEndDt=&srchKey=&srchText=","publisher":"South Korean Financial Services Commission","published_at":"2021-09-17","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Historical Bithumb VASP-report acceptance and Korean regulatory perimeter.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:yonhap","title":"Bithumb retrieves most bitcoin mistakenly credited to customers","url":"https://en.yna.co.kr/view/AEN20260207001551320","publisher":"Yonhap News Agency","published_at":"2026-02-07","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent incident chronology, internal-credit scale and affected-customer reporting.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:market-share","title":"Bithumb market share falls after fee waivers tied to bitcoin fiasco end","url":"https://www.koreatimes.co.kr/economy/cryptocurrency/20260222/bithumb-market-share-falls-after-fee-waivers-tied-to-bitcoin-fiasco-end","publisher":"The Korea Times","published_at":"2026-02-22","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent post-incident fee campaign and domestic market-share estimate.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:ipo","title":"Bithumb IPO delayed again after bitcoin payout error","url":"https://en.sedaily.com/finance/2026/03/03/bithumb-ipo-delayed-again-after-43-billion-bitcoin","publisher":"Seoul Economic Daily","published_at":"2026-03-03","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent reporting on IPO timetable, governance scrutiny and incident impact.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:bithumb:governance","title":"Bithumb bitcoin mishap casts doubt on CEO third term","url":"https://www.koreatimes.co.kr/economy/cryptocurrency/20260210/bithumb-bitcoin-mishap-casts-doubt-on-ceo-lee-jae-wons-third-term","publisher":"The Korea Times","published_at":"2026-02-10","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent governance and control-accountability context.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:bithumb:status","field_path":"status.operating_state","assertion":"Bithumb remained an operating Korean exchange at the review date while regulators reviewed internal-control failures tied to a February 2026 ledger error.","value":"operating_under_control_remediation","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-incident","source:bithumb:fsc-controls","source:bithumb:reports","source:bithumb:market-share"],"evidence_locator":"Current regulator follow-up, corporate reporting and independent market reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:outcome","field_path":"outcome.label","assertion":"Bithumb is classified as an operating domestic leader under control remediation, not as insolvent or closed.","value":"operating_domestic_leader_with_control_failure","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:fsc-incident","source:bithumb:fsc-controls","source:bithumb:operator-incident","source:bithumb:market-share"],"evidence_locator":"The incident involved erroneous internal credits with reported recovery, while the venue remained active in Korean market-share reporting.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Bithumb is a Korean custodial spot exchange.","value":"Bithumb is a Korean custodial spot exchange.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:vasp","source:bithumb:reports"],"evidence_locator":"Regulatory and reporting-entity records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Customers trade through an internal exchange ledger.","value":"Customers trade through an internal exchange ledger.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-incident","source:bithumb:operator-incident"],"evidence_locator":"Incident mechanics demonstrate off-chain credits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Domestic regulation and distribution are central to its operating model.","value":"Domestic regulation and distribution are central to its operating model.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:vasp","source:bithumb:market-share"],"evidence_locator":"Korean registration and domestic share reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Bithumb reported 620,000 BTC of erroneous internal credits.","value":"Bithumb reported 620,000 BTC of erroneous internal credits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:operator-incident","source:bithumb:fsc-incident","source:bithumb:yonhap"],"evidence_locator":"Operator, regulator and independent incident records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"The operator reported recovering 618,212 BTC, or 99.7% of the credits.","value":"The operator reported recovering 618,212 BTC, or 99.7% of the credits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:operator-incident"],"evidence_locator":"Operator recovery notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The FSC later identified control deficiencies and had not yet finalized sanctions.","value":"The FSC later identified control deficiencies and had not yet finalized sanctions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-controls"],"evidence_locator":"April inspection update.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"The incident was an internal rewards and ledger error rather than an on-chain exploit.","value":"The incident was an internal rewards and ledger error rather than an on-chain exploit.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:operator-incident","source:bithumb:fsc-incident"],"evidence_locator":"Incident descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Fee promotions were tied to Bithumb’s post-incident market-share effort.","value":"Fee promotions were tied to Bithumb’s post-incident market-share effort.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:market-share"],"evidence_locator":"Independent market reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Reported recovery does not by itself prove control remediation.","value":"Reported recovery does not by itself prove control remediation.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:operator-incident","source:bithumb:fsc-controls"],"evidence_locator":"Recovery and later inspection are distinct.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Bithumb used fee waivers and promotions to compete for domestic share.","value":"Bithumb used fee waivers and promotions to compete for domestic share.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:market-share","source:bithumb:operator-incident"],"evidence_locator":"Independent share report and rewards incident.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Bithumb was pursuing an IPO whose timetable faced renewed uncertainty.","value":"Bithumb was pursuing an IPO whose timetable faced renewed uncertainty.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:ipo"],"evidence_locator":"Independent corporate-finance reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"Control design, not only customer recovery, became a regulator focus.","value":"Control design, not only customer recovery, became a regulator focus.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-controls"],"evidence_locator":"Inspection findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Bithumb uses custodial account balances and internal matching.","value":"Bithumb uses custodial account balances and internal matching.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-incident","source:bithumb:operator-incident"],"evidence_locator":"Ledger and recovery mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Fee policy can change domestic trading share and immediate fee capture.","value":"Fee policy can change domestic trading share and immediate fee capture.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:market-share"],"evidence_locator":"Post-waiver share reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"A current audited customer-liability coverage ratio was not found in the reviewed record.","value":"A current audited customer-liability coverage ratio was not found in the reviewed record.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bithumb:reports","source:bithumb:fsc-controls"],"evidence_locator":"Disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Reviewed current sources do not identify a live Bithumb exchange token.","value":"Reviewed current sources do not identify a live Bithumb exchange token.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bithumb:reports","source:bithumb:vasp","source:bithumb:operator-incident"],"evidence_locator":"Current corporate, regulatory and operator-source review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Trading economics accrue to the operating company rather than automatically to users.","value":"Trading economics accrue to the operating company rather than automatically to users.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:reports","source:bithumb:market-share"],"evidence_locator":"Corporate and fee-competition boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"A future IPO security would be distinct from an exchange utility token.","value":"A future IPO security would be distinct from an exchange utility token.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:ipo"],"evidence_locator":"Corporate-finance boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Ledger controls and reconciliation were the direct remediation domain identified by regulators.","value":"Ledger controls and reconciliation were the direct remediation domain identified by regulators.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-incident","source:bithumb:fsc-controls"],"evidence_locator":"Regulator response.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Staged deployment and balance ceilings could have contained the error.","value":"Staged deployment and balance ceilings could have contained the error.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:fsc-incident","source:bithumb:operator-incident"],"evidence_locator":"Analyst counterfactual grounded in the incident mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"The evidence does not prove fee promotion caused the software error.","value":"The evidence does not prove fee promotion caused the software error.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bithumb:market-share","source:bithumb:operator-incident"],"evidence_locator":"Separate marketing and technical records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Internal-control deficiencies were identified by the FSC.","value":"Internal-control deficiencies were identified by the FSC.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-controls"],"evidence_locator":"Regulator inspection update.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Operator recovery figures are not a final audited loss determination.","value":"Operator recovery figures are not a final audited loss determination.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:operator-incident","source:bithumb:fsc-incident"],"evidence_locator":"Different evidence scopes.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Final sanctions, loss and IPO consequences remain unknown.","value":"Final sanctions, loss and IPO consequences remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bithumb:fsc-controls","source:bithumb:ipo"],"evidence_locator":"Open regulatory and corporate processes.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Bithumb completed the Korean VASP reporting process in 2021.","value":"Bithumb completed the Korean VASP reporting process in 2021.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:vasp"],"evidence_locator":"Official regulator record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The exchange remained a material domestic venue after the incident.","value":"The exchange remained a material domestic venue after the incident.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:bithumb:market-share"],"evidence_locator":"Independent market-share reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"The lifecycle call is operating under remediation rather than failed.","value":"The lifecycle call is operating under remediation rather than failed.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:fsc-controls","source:bithumb:market-share"],"evidence_locator":"Regulatory follow-up and continuing market activity.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Final regulator action and root-cause disclosure would directly change the control assessment.","value":"Final regulator action and root-cause disclosure would directly change the control assessment.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:fsc-controls","source:bithumb:fsc-incident"],"evidence_locator":"Open regulatory process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Sustained share without fee waivers is a stronger demand signal than temporary promotion volume.","value":"Sustained share without fee waivers is a stronger demand signal than temporary promotion volume.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:bithumb:market-share"],"evidence_locator":"Independent fee-period comparison.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Audited incident cost and current liability coverage remain unknown.","value":"Audited incident cost and current liability coverage remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:bithumb:reports","source:bithumb:fsc-controls"],"evidence_locator":"Disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:metric:domestic-share","field_path":"metrics[metric:bithumb:domestic-share:2026-02-22].value","assertion":"Approximate Korean spot-market share after fee waivers was 25 PERCENT for the stated scope and date.","value":25,"as_of":"2026-02-22","confidence":"high","kind":"fact","source_ids":["source:bithumb:market-share"],"evidence_locator":"Source observation checked at 2026-08-03T21:15:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:event:ledger-error","field_path":"events[event:bithumb:ledger-error]","assertion":"A rewards-processing error created 620,000 BTC of erroneous internal account credits.","value":"2026-02-06","as_of":"2026-02-06","confidence":"high","kind":"fact","source_ids":["source:bithumb:operator-incident","source:bithumb:fsc-incident","source:bithumb:yonhap"],"evidence_locator":"Operator, regulator and independent incident records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:event:recovery-report","field_path":"events[event:bithumb:recovery-report]","assertion":"Bithumb reported recovering 618,212 BTC of erroneous ledger credits.","value":"2026-02-07","as_of":"2026-02-07","confidence":"high","kind":"fact","source_ids":["source:bithumb:operator-incident"],"evidence_locator":"Operator notice; not an on-chain asset recovery figure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:bithumb:event:control-findings","field_path":"events[event:bithumb:control-findings]","assertion":"The FSC reported control deficiencies and a pending sanction-review process.","value":"2026-04-06","as_of":"2026-04-06","confidence":"high","kind":"fact","source_ids":["source:bithumb:fsc-controls"],"evidence_locator":"Official inspection update.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T21:15:00Z","next_review_at":"2026-08-10T21:15:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Final sanctions","Final incident loss","Current audited reserve coverage","Final IPO date"]},"extensions":{"legacy_origin":"mid_exchanges","identity_boundary":"The 620,000 BTC figure was an erroneous internal ledger credit, not evidence that Bithumb transferred or owned 620,000 on-chain bitcoin. Operator recovery percentages, regulator findings, corporate financial statements and the Korean spot-market venue are related but separate evidence types.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, reserve snapshots and tokens are kept separate.","Incident figures are reported ledger amounts and must not be presented as actual custody assets or a realized $44 billion loss.","The market-share value is an approximate independent domestic spot-market estimate after temporary fee waivers ended, not global exchange share."],"explicit_unknowns":["Final regulatory sanctions from the 2026 inspections","Net realized loss and insurance treatment from the ledger error","Current audited customer-asset and liability coverage","Final IPO timetable and governance changes"]}}', '{"kind":"cex","slug":"bithumb","lifecycle":"mid","operating_model":"Custodial Korean-won spot exchange using an internal order and balance ledger.","product_cohort":"centralized_spot_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"not_identified","token_symbol":null,"token_launch_date":null,"token_launch_timing":"unknown","token_strategy":"no_current_venue_token_identified","token_source_url":"https://www.bithumbcorp.com/ko/company/report.php","metric_type":"market_share","metric_unit":"percent","metric_window":"post_incident_observation","metric_as_of":"2026-02-22","metric_observed_at":"2026-08-03T21:15:00Z","comparability_key":"cex|centralized_spot_exchange|market_share|percent|domestic_observation","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"The 620,000 BTC figure was an erroneous internal ledger credit, not evidence that Bithumb transferred or owned 620,000 on-chain bitcoin. Operator recovery percentages, regulator findings, corporate financial statements and the Korean spot-market venue are related but separate evidence types.","source_count":9},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_e_profiles_0095 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'quadrigacx', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:quadrigacx","type":"cex","slug":"quadrigacx","name":"QuadrigaCX","aliases":["Quadriga","0984750 B.C. Ltd."]},"classification":{"subtype":"failed Canadian custodial spot exchange and bankruptcy estate","tags":["custodial","spot","failed","fraud-finding","bankruptcy","creditor-recovery"],"chains":[],"jurisdictions":["Canada"]},"status":{"operating_state":"closed_bankruptcy_estate","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:status"]},"outcome":{"label":"failed_fraud_with_partial_creditor_recovery","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:quadrigacx:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"QuadrigaCX was a Canadian custodial crypto exchange that held customer assets and maintained an internal trading ledger. It stopped operating in 2019 and is now only a bankruptcy estate administered by Ernst & Young. This report therefore separates the dead venue from the continuing claims process. A trustee distribution is estate recovery, not evidence that Quadriga has reopened or that customers recovered their original crypto.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:what_it_is:1","claim:quadrigacx:section:what_it_is:2","claim:quadrigacx:section:what_it_is:3"]},"what_happened":{"body":"Quadriga lost access to normal operations after founder Gerald Cotten died in December 2018, but the later OSC investigation found that the central problem was not simply lost cold-wallet keys. Staff concluded that Cotten controlled the business, created false balances, traded against customers and diverted assets, producing a C$169 million shortfall. The company entered bankruptcy, and the trustee later paid an interim dividend on accepted claims.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:what_happened:1","claim:quadrigacx:section:what_happened:2","claim:quadrigacx:section:what_happened:3"]},"why_this_outcome":{"body":"Quadriga concentrated custody, accounting, trading and authority in one founder without effective internal controls or independent oversight. That let fabricated account balances and self-dealing remain hidden while customer deposits funded withdrawals and losses. The market downturn exposed the gap because new inflows could no longer cover obligations. Cotten’s death removed the only operator with complete knowledge, but OSC staff found the financial hole already existed.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:why_this_outcome:1","claim:quadrigacx:section:why_this_outcome:2","claim:quadrigacx:section:why_this_outcome:3"]},"strategic_choices":{"body":"Quadriga chose founder-controlled wallets, weak books, no meaningful segregation and no effective checks on proprietary activity. It also operated without securities registration while customers believed balances represented assets held for them. Those were not ordinary startup tradeoffs; they removed the controls that could have exposed misuse. Once the exchange failed, bankruptcy converted customer positions into claims at court-fixed values, shifting control from the venue to the trustee.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:strategic_choices:1","claim:quadrigacx:section:strategic_choices:2","claim:quadrigacx:section:strategic_choices:3"]},"operating_model":{"body":"Customers deposited fiat and crypto with Quadriga and traded balances on its internal ledger. The exchange and Cotten controlled the wallets, payment processors and records, while reported balances could exceed real assets. According to OSC staff, later deposits were used to satisfy earlier withdrawals and fund Cotten’s trading and personal spending. After bankruptcy, EY—not the exchange—validated claims and distributed available Canadian-dollar estate funds.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:operating_model:1","claim:quadrigacx:section:operating_model:2","claim:quadrigacx:section:operating_model:3"]},"token_and_value_capture":{"body":"The reviewed regulator and trustee record does not identify a Quadriga venue token. Value was captured through exchange fees and, according to OSC staff, through Cotten’s unauthorized use of customer assets. Customers held account claims, not equity or a protected reserve token. In bankruptcy those balances became Canadian-dollar proven claims using court-fixed exchange rates, so the interim distribution cannot be read as a token return or original-asset repayment.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:token_and_value_capture:1","claim:quadrigacx:section:token_and_value_capture:2","claim:quadrigacx:section:token_and_value_capture:3"]},"counterfactual":{"body":"Independent custody controls, wallet reconciliation, separation of customer assets, audited books and limits on founder trading would likely have exposed the shortfall much earlier. Registration and credible oversight could have forced those controls or stopped the venue from taking more deposits. No control can guarantee survival, but Quadriga’s failure required multiple basic protections to be absent at once. A normal key-management plan alone would not have fixed fabricated balances and asset diversion.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:counterfactual:1","claim:quadrigacx:section:counterfactual:2","claim:quadrigacx:section:counterfactual:3"]},"risks_and_unknowns":{"body":"For the venue, the risk is settled: it is closed and will not resume normal exchange operations. For creditors, the open risks are estate costs, disputed claims, tax and legal reserves, conversion-date effects and whether more assets are found. The first interim dividend was 13.094156% of proven claims before the statutory levy, not a final recovery rate. Individual outcomes differ by accepted claim, original asset and market move after the conversion date.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:risks_and_unknowns:1","claim:quadrigacx:section:risks_and_unknowns:2","claim:quadrigacx:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Quadriga grew into a major Canadian exchange, accumulated customer liabilities without matching assets and collapsed after Cotten’s death in late 2018. Bankruptcy and the OSC investigation replaced the lost-keys story with a documented fraud-and-controls explanation. By 2023 the trustee could distribute a first interim dividend, but the exchange itself remained dead. Its lifecycle is failure followed by estate recovery, not a turnaround or relaunch.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:lifecycle:1","claim:quadrigacx:section:lifecycle:2","claim:quadrigacx:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch the EY document centre for a final distribution, reserve releases, disputed-claim decisions and any newly recovered assets. The final creditor outcome improves only if more estate value becomes distributable after costs and claims. Nothing in the current record supports reopening the exchange. For future CEX analysis, Quadriga’s durable signals are founder concentration, unverifiable internal balances, weak segregation and a narrative that blamed key access before forensic accounting showed a deeper hole.","as_of":"2026-08-03","claim_ids":["claim:quadrigacx:section:outlook_and_watch:1","claim:quadrigacx:section:outlook_and_watch:2","claim:quadrigacx:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:quadrigacx:customer-liabilities:2019-04-15","dimension":"customer_liabilities","label":"Customer liabilities identified by OSC staff","value":215000000,"unit":"cad","currency":"CAD","window":{"start":null,"end":"2019-04-15","definition":"collapse reconstruction"},"as_of":"2019-04-15","method":"OSC forensic balance-sheet reconstruction.","scope":{"product":"QuadrigaCX customer obligations","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:quadrigacx:metric:customer-liabilities"],"quality_flags":["regulator_reconstruction","historical","not_additive_with_shortfall"]},{"id":"metric:quadrigacx:customer-shortfall:2019-04-15","dimension":"customer_shortfall","label":"Customer shortfall identified by OSC staff","value":169000000,"unit":"cad","currency":"CAD","window":{"start":null,"end":"2019-04-15","definition":"collapse reconstruction"},"as_of":"2019-04-15","method":"OSC forensic balance-sheet reconstruction.","scope":{"product":"QuadrigaCX customer obligations less identified assets","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:quadrigacx:metric:customer-shortfall"],"quality_flags":["regulator_reconstruction","historical","not_additive_with_liabilities_or_assets"]},{"id":"metric:quadrigacx:first-interim-dividend:2023-05-12","dimension":"creditor_recovery","label":"First interim dividend on proven claims","value":13.094156,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2023-05-12","definition":"first interim distribution"},"as_of":"2023-05-12","method":"Trustee-declared dividend before statutory levy.","scope":{"product":"Accepted proven claims in the Quadriga bankruptcy","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:quadrigacx:metric:first-interim-dividend"],"quality_flags":["interim_not_final","less_statutory_levy","court_fixed_claim_values","not_original_asset_recovery"]}],"events":[{"id":"event:quadrigacx:closure","type":"closure","date":"2019-02-05","description":"Quadriga sought creditor protection after stopping normal exchange operations.","claim_ids":["claim:quadrigacx:event:closure"]},{"id":"event:quadrigacx:bankruptcy","type":"bankruptcy","date":"2019-04-15","description":"Quadriga entered bankruptcy and claims were valued using court-fixed conversion rates.","claim_ids":["claim:quadrigacx:event:bankruptcy"]},{"id":"event:quadrigacx:osc-findings","type":"regulatory_finding","date":"2020-06-11","description":"OSC staff published findings that founder fraud caused the collapse.","claim_ids":["claim:quadrigacx:event:osc-findings"]},{"id":"event:quadrigacx:interim-dividend","type":"recovery","date":"2023-05-12","description":"The trustee declared a 13.094156% interim dividend on proven claims before the levy.","claim_ids":["claim:quadrigacx:event:interim-dividend"]}],"sources":[{"id":"source:quadrigacx:osc-release","title":"OSC publishes investigative report on QuadrigaCX","url":"https://www.newswire.ca/news-releases/osc-publishes-investigative-report-of-quadrigacx-871268566.html","publisher":"Ontario Securities Commission via Canada Newswire","published_at":"2020-06-11","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"OSC staff conclusion, affected-investor count and aggregate loss estimate.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:quadrigacx:osc-funds","title":"Where did the Quadriga funds go?","url":"https://www.osc.gov.on.ca/quadrigacxreport/where-did-the-funds-go.html","publisher":"Ontario Securities Commission","published_at":"2020-06-11","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"C$215 million customer liabilities, C$46 million identified assets and C$169 million shortfall breakdown.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:quadrigacx:osc-conclusion","title":"QuadrigaCX investigation: conclusion","url":"https://www.osc.gov.on.ca/quadrigacxreport/conclusion.html","publisher":"Ontario Securities Commission","published_at":"2020-06-11","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"OSC staff findings on registration, asset handling, misleading statements and enforcement limitations.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:quadrigacx:osc-report","title":"QuadrigaCX: a review by staff of the Ontario Securities Commission","url":"https://www.osc.gov.on.ca/quadrigacxreport/web/files/QuadrigaCX-A-Review-by-Staff-of-the-Ontario-Securities-Commission.pdf","publisher":"Ontario Securities Commission","published_at":"2020-04-14","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Full staff investigative record and methodology.","direct_http_status":200,"access_method":"direct_pdf"},{"id":"source:quadrigacx:ey-distribution","title":"QuadrigaCX second interim status report","url":"https://documentcentre.ey.com/api/Document/download?docId=37250&language=EN","publisher":"Ernst & Young Inc., bankruptcy trustee","published_at":"2023-05-12","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"First interim dividend of 13.094156% of proven claims and reserve for future administration.","direct_http_status":200,"access_method":"direct_pdf"},{"id":"source:quadrigacx:ey-estate","title":"QuadrigaCX court and creditor document centre","url":"https://documentcentre.ey.com/#/detail-engmt?eid=337","publisher":"Ernst & Young Inc., bankruptcy trustee","published_at":null,"accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Current official estate document index and bankruptcy-estate boundary.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:quadrigacx:coindesk","title":"Quadriga was a Ponzi scheme, Ontario securities regulator says","url":"https://www.coindesk.com/markets/2020/06/11/quadriga-was-a-ponzi-scheme-ontario-securities-regulator-says","publisher":"CoinDesk","published_at":"2020-06-11","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent account of OSC staff findings and loss breakdown.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:quadrigacx:bloomberg","title":"Quadriga downfall stemmed from founder fraud, regulators find","url":"https://news.bloomberglaw.com/banking-law/quadriga-downfall-stemmed-from-founders-fraud-regulators-find","publisher":"Bloomberg Law","published_at":"2020-06-11","accessed_at":"2026-08-03T21:15:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T21:15:00Z","content_hash":null,"evidence_locator":"Independent account of the regulator findings and enforcement context.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:quadrigacx:status","field_path":"status.operating_state","assertion":"QuadrigaCX is closed and its remaining affairs are handled through the bankruptcy estate; the exchange is not operating.","value":"closed_bankruptcy_estate","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-release","source:quadrigacx:ey-estate","source:quadrigacx:ey-distribution"],"evidence_locator":"Regulator collapse report and current trustee estate records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:outcome","field_path":"outcome.label","assertion":"QuadrigaCX is classified as a failed exchange caused primarily by founder fraud, with only partial creditor recovery.","value":"failed_fraud_with_partial_creditor_recovery","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:quadrigacx:osc-funds","source:quadrigacx:osc-conclusion","source:quadrigacx:osc-report","source:quadrigacx:ey-distribution","source:quadrigacx:coindesk"],"evidence_locator":"OSC staff forensic findings and trustee dividend record.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"QuadrigaCX was a Canadian custodial exchange.","value":"QuadrigaCX was a Canadian custodial exchange.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-report","source:quadrigacx:osc-conclusion"],"evidence_locator":"Regulator business-model findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"The exchange is closed and the remaining process is a bankruptcy estate.","value":"The exchange is closed and the remaining process is a bankruptcy estate.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:ey-estate","source:quadrigacx:ey-distribution"],"evidence_locator":"Trustee records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Estate distributions do not represent renewed exchange operation.","value":"Estate distributions do not represent renewed exchange operation.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:quadrigacx:ey-distribution"],"evidence_locator":"Bankruptcy-dividend context.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"The OSC found that founder conduct, not only lost keys, caused the collapse.","value":"The OSC found that founder conduct, not only lost keys, caused the collapse.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-release","source:quadrigacx:osc-report","source:quadrigacx:osc-conclusion"],"evidence_locator":"Staff investigative conclusion.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"The OSC calculated a C$169 million customer shortfall.","value":"The OSC calculated a C$169 million customer shortfall.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-funds"],"evidence_locator":"Regulator loss breakdown.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The trustee declared an interim dividend for creditors with proven claims.","value":"The trustee declared an interim dividend for creditors with proven claims.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:ey-distribution"],"evidence_locator":"Trustee status report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Cotten exercised broad control without adequate oversight.","value":"Cotten exercised broad control without adequate oversight.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-report","source:quadrigacx:osc-conclusion"],"evidence_locator":"Regulator governance findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"OSC staff found fabricated trading and misuse of customer assets.","value":"OSC staff found fabricated trading and misuse of customer assets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-funds","source:quadrigacx:osc-report"],"evidence_locator":"Forensic loss categories.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Cotten’s death exposed rather than created most of the shortfall.","value":"Cotten’s death exposed rather than created most of the shortfall.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:quadrigacx:osc-release","source:quadrigacx:osc-funds"],"evidence_locator":"Regulator causal finding.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Quadriga operated without registration and adequate controls.","value":"Quadriga operated without registration and adequate controls.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-conclusion","source:quadrigacx:osc-report"],"evidence_locator":"OSC findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Customer assets were not reliably segregated from founder activity.","value":"Customer assets were not reliably segregated from founder activity.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-funds","source:quadrigacx:osc-report"],"evidence_locator":"Forensic tracing.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"Bankruptcy converted exchange balances into estate claims.","value":"Bankruptcy converted exchange balances into estate claims.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:quadrigacx:ey-distribution"],"evidence_locator":"Trustee claim and dividend process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Quadriga held customer assets and maintained an internal ledger.","value":"Quadriga held customer assets and maintained an internal ledger.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-report","source:quadrigacx:osc-funds"],"evidence_locator":"Regulator operating-model findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"OSC staff found later deposits were used to meet withdrawals and other spending.","value":"OSC staff found later deposits were used to meet withdrawals and other spending.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-release","source:quadrigacx:osc-funds"],"evidence_locator":"Ponzi-like flow findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"EY administers claims and distributions after closure.","value":"EY administers claims and distributions after closure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:ey-distribution","source:quadrigacx:ey-estate"],"evidence_locator":"Trustee records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Reviewed OSC and trustee sources do not identify a Quadriga exchange token.","value":"Reviewed OSC and trustee sources do not identify a Quadriga exchange token.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:quadrigacx:osc-report","source:quadrigacx:ey-distribution"],"evidence_locator":"Regulator and estate record review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"OSC staff found unauthorized founder value extraction from customer assets.","value":"OSC staff found unauthorized founder value extraction from customer assets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:quadrigacx:osc-funds","source:quadrigacx:osc-conclusion"],"evidence_locator":"Forensic loss findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:quadrigacx:sec